import fs from 'node:fs';

const raw = fs.readFileSync(process.argv[2], 'utf8');
const txt = raw.replace(new RegExp(String.fromCharCode(27) + '\\[[0-9;]*m', 'g'), '');
const lines = txt.split('\n');
const reqs = {};
const out = {};
const urls = {};
let cur = null;
for (const line of lines) {
  const m = line.match(/reqId: "(req-[a-z0-9]+)"/);
  if (m) cur = m[1];
  const mm = line.match(/"method": "([A-Z]+)"/);
  if (mm && cur) reqs[cur] = { method: mm[1] };
  const uu = line.match(/"url": "([^"]+)"/);
  if (uu && cur && reqs[cur]) reqs[cur].url = uu[1];
  const sc = line.match(/"statusCode": (\d+)/);
  if (sc && cur && reqs[cur]) {
    const k = reqs[cur].method + ' ' + sc[1];
    out[k] = (out[k] || 0) + 1;
    if (sc[1] !== '200' && reqs[cur].url) urls[k + ' ' + reqs[cur].url] = true;
  }
}
console.log(out);
console.log(Object.keys(urls).slice(0, 10));

